import { useState } from 'react';
import { JxButton, JxCalendar } from '@jinx-ui/react';

function startOfDay(date: Date): Date {
  const result = new Date(date);
  result.setHours(0, 0, 0, 0);
  return result;
}

function addDays(date: Date, days: number): Date {
  const result = new Date(date);
  result.setDate(result.getDate() + days);
  return result;
}

interface ReportDatePickerProps {
  onChange?: (date: Date) => void;
}

export default function ReportDatePicker({ onChange }: ReportDatePickerProps) {
  const [selectedDate, setSelectedDate] = useState<Date>(() => startOfDay(new Date()));

  const handleChange = (date: Date) => {
    const normalized = startOfDay(date);
    setSelectedDate(normalized);
    onChange?.(normalized);
  };

  const quickOptions = [
    { label: 'Сегодня', getDate: () => startOfDay(new Date()) },
    { label: 'Вчера', getDate: () => addDays(startOfDay(new Date()), -1) },
    { label: 'Неделя назад', getDate: () => addDays(startOfDay(new Date()), -7) },
  ];

  return (
    <div className="jx-stack" style={{ gap: 'var(--jx-space-3)' }}>
      <div className="jx-inline" style={{ gap: 'var(--jx-space-2)' }}>
        {quickOptions.map((option) => (
          <JxButton
            key={option.label}
            variant="secondary"
            size="sm"
            onPress={() => handleChange(option.getDate())}
          >
            {option.label}
          </JxButton>
        ))}
      </div>
      <JxCalendar value={selectedDate} onValueChange={handleChange} />
    </div>
  );
}

